{
  "justification": "Unprompted salience is dominated by health (NHS) and disease/contamination (foot-and-mouth, BSE), with education and crime also high, while EU/immigration and the economy are notable. Because this instrument records salience not direction, I weight Care and Sanctity highest, followed by Loyalty and Authority, with Equality and Proportionality present but secondary.",
  "foundations": [
    {
      "foundation": "care",
      "basis": "NHS/Hospitals/Healthcare; Education/Schools; Crime/Law and order/Violence/Vandalism (harm to victims); Housing; Poverty/Inequality; Aids; Drug abuse; Animal welfare",
      "weight": 0.28
    },
    {
      "foundation": "sanctity",
      "basis": "Foot And Mouth Outbreak/Farming Crisis; BSE/Beef; Pollution/Environment; Aids; Drug abuse; Genetically Modified Foods; Animal welfare; Morality/Individual behaviour",
      "weight": 0.26
    },
    {
      "foundation": "loyalty",
      "basis": "Race relations/Immigration/Immigrants; Common Market/EU/Europe/Single European Currency; Defence/Foreign affairs/International terrorism; Countryside/Rural life; Northern Ireland",
      "weight": 0.16
    },
    {
      "foundation": "authority",
      "basis": "Crime/Law and order/Violence/Vandalism; Morality/Individual behaviour; Defence/Foreign affairs/International terrorism; Local government/Council tax/Poll tax",
      "weight": 0.12
    },
    {
      "foundation": "equality",
      "basis": "Poverty/Inequality; Pensions/Social security; Housing; Education/Schools; Low pay/Minimum wage/Fair wages",
      "weight": 0.10
    },
    {
      "foundation": "proportionality",
      "basis": "Economy/Economic situation; Unemployment/Factory closure/Lack of industry; Taxation; Petrol prices/Fuel; Inflation/Prices; Transport/Public transport; Local government/Council tax/Poll tax",
      "weight": 0.08
    }
  ]
}
